/* story-form-8 — Volume/Ledger beat parity (extends form-7 drama styles) */
.volume-beat-card, .ledger-beat-card {
  padding: 0.75rem 0.9rem;
  margin: 0.4rem 0;
  border-left: 3px solid #7eb6c9;
  background: rgba(18,12,8,.75);
  color: #f2e6d8;
}
.ledger-beat-card { border-left-color: #c4a574; }
.volume-beat-card.is-live, .ledger-beat-card.is-live {
  box-shadow: inset 0 0 0 1px rgba(196,92,62,.35);
  border-left-color: #c45c3e;
}
.volume-beat-card.is-done, .ledger-beat-card.is-done { opacity: 0.65; }

