function storyForm8() {
  return state.questPack?.storyForm8 || state.storyForm8 || null;
}

function allArcBeatCardLists() {
  const f7 = storyForm7() || {};
  const f8 = storyForm8() || {};
  return [
    { priority: 95, cards: f7.antennaOpJournalBeatCards, banner: f7.activeArcBeatBanner, when: f7.activeArcBeatBanner?.when, kind: 'antenna' },
    { priority: 94, cards: f8.volumeOpJournalBeatCards, banner: f8.activeArcBeatBanners?.[0], when: f8.activeArcBeatBanners?.[0]?.when, kind: 'volume' },
    { priority: 93, cards: f8.ledgerOpJournalBeatCards, banner: f8.activeArcBeatBanners?.[1], when: f8.activeArcBeatBanners?.[1]?.when, kind: 'ledger' },
  ];
}

function liveBeatFromCards(cards) {
  for (const c of cards || []) {
    if ((c.requiresFlags||[]).length && !c.requiresFlags.every((f) => storyFlag(f))) continue;
    if (c.doneFlag && storyFlag(c.doneFlag)) continue;
    if (c.doneFlagAny?.some((f) => storyFlag(f))) continue;
    return c;
  }
  return null;
}

function activeArcBeatBannerHtml() {
  const lists = allArcBeatCardLists()
    .filter((row) => row.banner && whenFlagsOk(row.when || {}))
    .sort((a, b) => b.priority - a.priority);
  for (const row of lists) {
    const beat = liveBeatFromCards(row.cards);
    if (!beat) continue;
    const ban = row.banner;
    const sceneShort = loc(beat.scene);
    const short = sceneShort.length > 72 ? sceneShort.slice(0, 70) + "…" : sceneShort;
    const line = (state.locale === "tr" ? ban.template.tr : ban.template.en)
      .replace("{beatTitle}", loc(beat.title))
      .replace("{sceneShort}", short);
    const neighbor = beat.cast?.[0] || "n1";
    return `<div class="rp-arc-beat-banner" data-testid="${ban.testId}"><span>${line}</span>
      <button class="rp-btn rp-btn--primary" type="button" data-action="open-neighbor" data-id="${neighbor}">${loc(ban.cta)}</button></div>`;
  }
  return "";
}

